options nomprint nosymbolgen;
libname xin '/sasdata/arch/hhold';
%let dt=202112;

data d1;
  length HHID $10 RGN $1 IMTH $6 PWGT 8 NPER 8;
  infile datalines dsd truncover;
  input HHID $ RGN $ IMTH $ PWGT NPER;
  datalines;
  HHI0001,0,202112,270.87,881.78
  HHI0002,0,202112,238.77,143.69
  HHI0003,0,202112,617.77,800.85
  HHI0004,1,202112,37.93,138.48
  ;
run;

data d2;
  length HHID $10 RGN $1 LFST $2 PRXF $1 INCB $2;
  infile datalines dsd truncover;
  input HHID $ RGN $ LFST $ PRXF $ INCB $;
  datalines;
  HHI0001,0,N,N,N
  HHI0002,0,P,N,A
  HHI0003,0,R,I,N
  HHI0004,1,Y,E,I
  ;
run;

%macro runjob6(p=, lb=work, thr=0);
proc sort data=d1 out=_sd1; by HHID RGN; run;
proc sort data=d2 out=_sd2; by HHID RGN; run;
data _t1;
  merge _sd1(in=i1) _sd2(in=i2);
  by HHID RGN;
  if i1;
  if PWGT ge &thr;
  if IMTH = '' then IMTH = "&dt";
run;

data _t2;
  set _t1;
  if NPER > 0 then NPERR = round(100*NPER/PWGT, 0.01);
  else NPERR = .;
run;

proc summary data=_t2 nway;
  class RGN;
  var PWGT NPER;
  output out=agg1(drop=_type_ _freq_) mean=;
run;
data _t3; set _t2; run;

data &lb..o2;
  set _t3;
run;
%mend runjob6;

%runjob6(p=&dt);

